import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import Brand from "../components/ui/Brand";
import { useApp } from "../lib/AppContext";
const Login = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();
  const {
    notify
  } = useApp();
  const submit = event => {
    event.preventDefault();
    navigate("/dashboard");
    notify(`Welcome${email ? `, ${email.split("@")[0]}` : ""} · demo session`);
  };
  return <div className="login-screen">
      <div className="login-card">
        <Link to="/login" className="brand-link">
          <Brand />
        </Link>
        <div className="eyebrow">ADMINISTRATOR PORTAL</div>
        <h1>Welcome back</h1>
        <p>Sign in to manage community environmental reports.</p>
        <form onSubmit={submit}>
          <label htmlFor="email">Email address</label>
          <input id="email" type="email" value={email} onChange={event => setEmail(event.target.value)} placeholder="you@cegct.org" required />
          <label htmlFor="password">Password</label>
          <input id="password" type="password" value={password} onChange={event => setPassword(event.target.value)} placeholder="Enter your password" required />
          <button className="primary full" type="submit">
            Sign in <span>→</span>
          </button>
        </form>
        <small>
          Demo interface · Connect Supabase Auth to enable secure administrator
          sign-in.
        </small>
      </div>
    </div>;
};
export default Login;
